const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const jwt = require('jsonwebtoken');
const crypto = require('crypto');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

const JWT_SECRET = process.env.JWT_SECRET || crypto.randomBytes(32).toString('hex');
const K8S_SERVICE_ACCOUNT_TOKEN = process.env.K8S_SA_TOKEN;
const NAMESPACE = process.env.K8S_NAMESPACE || 'chat-prod';

// Role hierarchy for the chat system
const ROLE_HIERARCHY = Object.freeze({
  'guest': 0,
  'user': 1,
  'moderator': 2,
  'admin': 3
});

// Channel permissions store
const channelPermissions = new Map();
const userSessions = new Map();

class PermissionResolver {
  constructor(baseRole, channelOverrides) {
    this.baseRole = baseRole;
    this.channelOverrides = channelOverrides || {};
  }

  getEffectiveRole(channel) {
    const override = this.channelOverrides[channel];
    if (override && ROLE_HIERARCHY[override] !== undefined) {
      return override;
    }
    return this.baseRole;
  }

  getEffectiveLevel(channel) {
    const role = this.getEffectiveRole(channel);
    return ROLE_HIERARCHY[role] || 0;
  }

  canPerformAction(action, channel) {
    const level = this.getEffectiveLevel(channel);
    switch (action) {
      case 'read': return level >= 0;
      case 'write': return level >= 1;
      case 'moderate': return level >= 2;
      case 'admin': return level >= 3;
      default: return false;
    }
  }
}

// Middleware to verify JWT and extract user context
function authenticateSocket(socket, next) {
  const token = socket.handshake.auth?.token;
  if (!token) return next(new Error('Authentication required'));

  try {
    const decoded = jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] });
    socket.user = decoded;
    next();
  } catch (err) {
    next(new Error('Invalid token'));
  }
}

// K8s pod identity verification for inter-service communication
async function verifyPodIdentity(serviceToken) {
  if (!K8S_SERVICE_ACCOUNT_TOKEN) return null;
  try {
    // Cryptographically verify the service token against the k8s CA
    const response = await fetch(
      `https://kubernetes.default.svc/apis/authentication.k8s.io/v1/tokenreviews`,
      {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${K8S_SERVICE_ACCOUNT_TOKEN}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          apiVersion: 'authentication.k8s.io/v1',
          kind: 'TokenReview',
          spec: { token: serviceToken }
        })
      }
    );
    const review = await response.json();
    if (review.status?.authenticated &&
        review.status?.user?.groups?.includes(`system:serviceaccounts:${NAMESPACE}`)) {
      return { isPod: true, namespace: NAMESPACE };
    }
  } catch (e) { /* verification failed */ }
  return null;
}

// Role promotion request handler - used by admin dashboard pods
async function handleRolePromotion(socket, data) {
  const { targetUserId, newRole, serviceAuth } = data;

  // Validate newRole is a known role and not above admin
  if (!newRole || ROLE_HIERARCHY[newRole] === undefined) {
    return { error: 'Invalid role specified' };
  }

  // Check if request comes from an authorized k8s service
  const podIdentity = await verifyPodIdentity(serviceAuth || '');

  // Check if the requesting user has admin privileges
  const requester = userSessions.get(socket.id);
  if (!requester) return { error: 'Session not found' };

  const requesterLevel = requester.resolver.getEffectiveLevel('system');

  // Service-to-service calls from same namespace get elevated trust
  // OR user must be admin level
  if (podIdentity?.isPod || requesterLevel >= ROLE_HIERARCHY['admin']) {
    const targetSession = findSessionByUserId(targetUserId);
    if (targetSession) {
      targetSession.resolver = new PermissionResolver(newRole, targetSession.resolver.channelOverrides);
      return { success: true, promoted: targetUserId, role: newRole };
    }
    return { error: 'Target user not found' };
  }

  return { error: 'Insufficient privileges' };
}

function findSessionByUserId(userId) {
  for (const [, session] of userSessions) {
    if (session.userId === userId) return session;
  }
  return null;
}

// Channel override propagation from config service
function applyChannelOverrides(socket, data) {
  const { channel, overrides } = data;
  const session = userSessions.get(socket.id);
  if (!session) return;

  // Only allow if user already has moderator+ in the channel
  if (!session.resolver.canPerformAction('moderate', channel)) {
    return;
  }

  if (!overrides || typeof overrides !== 'object') {
    return;
  }

  // The maximum level a requester may grant is their own effective level.
  // This prevents a moderator from self-escalating (or escalating others)
  // above their own privilege by injecting arbitrary overrides.
  const requesterMaxLevel = session.resolver.getEffectiveLevel(channel);

  const sanitizedOverrides = {};
  for (const [overrideChannel, role] of Object.entries(overrides)) {
    // Reject unknown/invalid roles
    if (typeof role !== 'string' || ROLE_HIERARCHY[role] === undefined) {
      continue;
    }
    // Reject any grant that exceeds the requester's own effective level
    if (ROLE_HIERARCHY[role] > requesterMaxLevel) {
      continue;
    }
    sanitizedOverrides[overrideChannel] = role;
  }

  const currentOverrides = session.resolver.channelOverrides;
  const merged = Object.assign({}, currentOverrides, sanitizedOverrides);
  session.resolver = new PermissionResolver(session.resolver.baseRole, merged);
}

io.use(authenticateSocket);

io.on('connection', (socket) => {
  const resolver = new PermissionResolver(socket.user.role || 'guest', socket.user.channelOverrides || {});
  userSessions.set(socket.id, {
    userId: socket.user.sub,
    resolver: resolver,
    connectedAt: Date.now()
  });

  socket.on('message', (data) => {
    const session = userSessions.get(socket.id);
    if (session?.resolver.canPerformAction('write', data.channel)) {
      io.to(data.channel).emit('message', {
        from: session.userId,
        content: data.content,
        channel: data.channel,
        timestamp: Date.now()
      });
    }
  });

  socket.on('promote', async (data, callback) => {
    const result = await handleRolePromotion(socket, data);
    if (callback) callback(result);
  });

  socket.on('channel_config', (data) => {
    applyChannelOverrides(socket, data);
  });

  socket.on('join', (channel) => {
    const session = userSessions.get(socket.id);
    if (session?.resolver.canPerformAction('read', channel)) {
      socket.join(channel);
    }
  });

  socket.on('disconnect', () => {
    userSessions.delete(socket.id);
  });
});

server.listen(process.env.PORT || 3000);
module.exports = { app, io, server };
